test("refund and processed marker roll back together if processing fails", (t) => {
  const { dir, store } = fixture(t);
  const markProcessed = store.markProcessed.bind(store);
  store.markProcessed = () => { throw new Error("simulated processing failure"); };
  assert.throws(() => processEvent(store, POLICY, event()), /simulated processing failure/);
  assert.equal(store.listRefunds().length, 0);
  assert.equal(store.isProcessed("evt_test"), false);
  assert.deepEqual(snapshot(dir), {});
  store.markProcessed = markProcessed;
  const result = processEvent(store, POLICY, event());
  assert.equal(result.outcome, "processed");
  assert.equal(store.listRefunds()[0].id, "rfd_000001");
  assert.equal(new Store(dir).isProcessed("evt_test"), true);
});

test("duplicate cancellation leaves a pending-review refund cancelled without more audit", (t) => {
  const { dir, store } = fixture(t);
  processEvent(store, POLICY, event("evt_request", "refund.requested", 500001));
  const cancel = event("evt_cancel", "refund.cancelled");
  assert.equal(processEvent(store, POLICY, cancel).outcome, "processed");
  assert.equal(store.listRefunds()[0].status, "cancelled");
  const before = snapshot(dir);
  assert.equal(processEvent(store, POLICY, cancel).outcome, "duplicate");
  assert.deepEqual(snapshot(dir), before);
});
